pre.code:
// 语义色板（对齐自研现有 + 借鉴龙兵状态色）
$color-primary: #165dff;      // 品牌蓝（自研现有）
$color-brand: #f59e0b;        // 品牌橙（hero 默认）
$color-success: #19a918;      // 借鉴龙兵
$color-link: #108ee9;         // 借鉴龙兵
$color-warning: #feb22d;      // 借鉴龙兵
$color-error: #fa3a39;        // 借鉴龙兵
$color-hot: #ea3341;
$color-caption: #86909c;      // 次级灰（自研现有）
$color-body: #f5f6f7;         // 页面背景（自研现有）

// 字号阶梯（借鉴龙兵，rpx→px 换算）
$font-size: (icontext: 11px, caption: 12px, caption-lg: 13px, paragraph: 14px, title: 15px, title-lg: 16px, title-xl: 24px);

// 间距（严格 8 的倍数）
$space: (sm: 4px, md: 8px, lg: 16px);

// 字号类：f-icontext / f-caption / f-paragraph / f-title / f-title-lg / f-title-xl
// 颜色类：c-primary / c-link / c-warning / c-error / c-caption / c-paragraph
// 间距类：mg-sm/md/lg · mt-* · mb-* · ml-* · mr-* · pd-* · pt-* · pb-* · pl-* · pr-*
// Flex 类：flex / flex-1 / flex-column / flex-center / flex-between / flex-x-center
// 1px 高清线：.b-1px / .b-1px-t / .b-1px-b（scale(0.5) 实现）
// 省略：.ellipsis / .ellipsis-2 / .ellipsis-3
// 列表：.cell-list / .cell-item / .cell（iOS 风格单元格）
